tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlasq4, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 17', function test( t ) {
	t.strictEqual( dlasq4.length, 17, 'returns expected value' );
	t.end();
});

tape( 'the function computes an approximation to the smallest eigenvalue using values of d from the previous transform when `TTYPE` equals to -1', function test( t ) {
	var expected;
	var DMIN1;
	var DMIN2;
	var data;
	var DMIN;
	var N0IN;
	var DN1;
	var DN2;
	var out;
	var DN;
	var I0;
	var N0;
	var PP;
	var G;
	var Z;

	data = TTYPE_1;

	I0 = data.I0;
	N0 = data.N0;
	Z = new Float64Array( data.Z );
	PP = data.PP;
	N0IN = data.N0IN;
	DMIN = data.DMIN;
	DMIN1 = data.DMIN1;
	DMIN2 = data.DMIN2;
	DN = data.DN;
	DN1 = data.DN1;
	DN2 = data.DN2;
	G = data.G;

	out = new Float64Array( 3 );

	expected = new Float64Array( data.expectedOut );

	dlasq4( I0, N0, Z, data.strideZ, data.offsetZ, PP, N0IN, DMIN, DMIN1, DMIN2, DN, DN1, DN2, G, out, data.strideOut, data.offsetOut );
	t.strictEqual( isAlmostEqual( out, expected, 1 ), true, 'returns expected value' );
	t.end();
});

